@NonNull static File getCacheFile(Context context,long id,String source){
  File dir=new File(context.getCacheDir(),"images");
  try {
    if (!dir.exists())   dir.mkdir();
  } catch (SecurityException e) {
    // 处理安全异常，例如记录日志或抛出适当的运行时异常
    throw new RuntimeException("Failed to access or create cache directory", e);
  }
  return new File(dir,id + "_" + Math.abs(source.hashCode())+ ".png");
}
